// OrchestratorServiceHandler is an implementation of the bossanova.v1.OrchestratorService service.
type OrchestratorServiceHandler interface {
	// Daemon registry
	RegisterDaemon(context.Context, *connect.Request[v1.RegisterDaemonRequest]) (*connect.Response[v1.RegisterDaemonResponse], error)
	// PublishDaemonSnapshot is a unary fallback for networks that proxy normal
	// HTTPS but do not support Connect bidirectional streaming end-to-end.
	// Daemons authenticate with their RegisterDaemon session token and publish
	// the same snapshot shape used as the first DaemonStream event.
	PublishDaemonSnapshot(context.Context, *connect.Request[v1.PublishDaemonSnapshotRequest]) (*connect.Response[v1.PublishDaemonSnapshotResponse], error)
	// DaemonStream is the long-lived bidirectional channel between a daemon
	// and the orchestrator. Daemons push session deltas and other events;
	// the orchestrator pushes commands (proxy RPC invocations, transfer
	// directives, etc.). Replaces Heartbeat and SyncSessions.
	DaemonStream(context.Context, *connect.BidiStream[v1.DaemonEvent, v1.OrchestratorCommand]) error
	ListDaemons(context.Context, *connect.Request[v1.ListDaemonsRequest]) (*connect.Response[v1.ListDaemonsResponse], error)
	// Session transfer between daemons
	TransferSession(context.Context, *connect.Request[v1.TransferSessionRequest]) (*connect.Response[v1.TransferSessionResponse], error)
	// Proxied daemon RPCs (remote CLI → orchestrator → daemon)
	ProxyListSessions(context.Context, *connect.Request[v1.ProxyListSessionsRequest]) (*connect.Response[v1.ProxyListSessionsResponse], error)
	ProxyGetSession(context.Context, *connect.Request[v1.ProxyGetSessionRequest]) (*connect.Response[v1.ProxyGetSessionResponse], error)
	ProxyAttachSession(context.Context, *connect.Request[v1.ProxyAttachSessionRequest], *connect.ServerStream[v1.ProxyAttachSessionResponse]) error
	// Creates a new session on a chosen daemon, streaming setup output as it
	// runs and terminating with the created Session or an in-band error.
	// Routes to the daemon named by daemon_id (no session exists yet).
	ProxyCreateSession(context.Context, *connect.Request[v1.ProxyCreateSessionRequest], *connect.ServerStream[v1.ProxyCreateSessionResponse]) error
	ProxyStopSession(context.Context, *connect.Request[v1.ProxyStopSessionRequest]) (*connect.Response[v1.ProxyStopSessionResponse], error)
	ProxyPauseSession(context.Context, *connect.Request[v1.ProxyPauseSessionRequest]) (*connect.Response[v1.ProxyPauseSessionResponse], error)
	ProxyResumeSession(context.Context, *connect.Request[v1.ProxyResumeSessionRequest]) (*connect.Response[v1.ProxyResumeSessionResponse], error)
	// Wakes a stopped chat's tmux+claude. Routes to the owning daemon via the
	// reverse stream and waits for CommandResult{WakeChatResult}.
	ProxyWakeChat(context.Context, *connect.Request[v1.ProxyWakeChatRequest]) (*connect.Response[v1.ProxyWakeChatResponse], error)
	// Merges a session's PR via the owning daemon's reverse stream.
	ProxyMergeSession(context.Context, *connect.Request[v1.ProxyMergeSessionRequest]) (*connect.Response[v1.ProxyMergeSessionResponse], error)
	// Archives a session via the owning daemon's reverse stream.
	ProxyArchiveSession(context.Context, *connect.Request[v1.ProxyArchiveSessionRequest]) (*connect.Response[v1.ProxyArchiveSessionResponse], error)
	// Records or resumes a chat via the owning daemon's reverse stream.
	ProxyRecordChat(context.Context, *connect.Request[v1.ProxyRecordChatRequest]) (*connect.Response[v1.ProxyRecordChatResponse], error)
	// Deletes a chat via the owning daemon's reverse stream.
	ProxyDeleteChat(context.Context, *connect.Request[v1.ProxyDeleteChatRequest]) (*connect.Response[v1.ProxyDeleteChatResponse], error)
	// Switches a session's live chat to a different account (stop+swap+resume)
	// via the owning daemon's reverse stream. Routes by session_id
	// (FindSessionDaemon) with an optional GetChat authz check, like ProxyWakeChat.
	ProxySwitchSessionAccount(context.Context, *connect.Request[v1.ProxySwitchSessionAccountRequest]) (*connect.Response[v1.ProxySwitchSessionAccountResponse], error)
	// Lists the rotation accounts on the daemon owning session_id (web
	// account-switch picker). Routes by session_id (FindSessionDaemon) for authz
	// scope, like ProxySwitchSessionAccount. Accounts are metadata only — never
	// credentials. Optional provider filter ("" = all).
	ProxyListAccounts(context.Context, *connect.Request[v1.ProxyListAccountsRequest]) (*connect.Response[v1.ProxyListAccountsResponse], error)
	// Reads a chat's transcript via the owning daemon's reverse stream. Routes by
	// session_id (FindSessionDaemon) with a GetChat authz check, like ProxyWakeChat.
	ProxyGetChatTranscript(context.Context, *connect.Request[v1.ProxyGetChatTranscriptRequest]) (*connect.Response[v1.ProxyGetChatTranscriptResponse], error)
	// Sends a user message into a chat via the owning daemon's reverse stream.
	// Routes by agent_session_id (FindDaemonForChat) since the MCP send tool
	// carries no session_id.
	ProxySendChatMessage(context.Context, *connect.Request[v1.ProxySendChatMessageRequest]) (*connect.Response[v1.ProxySendChatMessageResponse], error)
	// Aggregates repos across all of the caller's live daemons, deduped by
	// origin URL, with the serving daemon IDs unioned per repo.
	ProxyListReposAggregated(context.Context, *connect.Request[v1.ProxyListReposAggregatedRequest]) (*connect.Response[v1.ProxyListReposAggregatedResponse], error)
	// Lists the installed agents on a single named daemon via its reverse stream.
	ProxyListAgents(context.Context, *connect.Request[v1.ProxyListAgentsRequest]) (*connect.Response[v1.ProxyListAgentsResponse], error)
	ProxyListRepoPRs(context.Context, *connect.Request[v1.ProxyListRepoPRsRequest]) (*connect.Response[v1.ProxyListRepoPRsResponse], error)
	ProxyListTrackerIssues(context.Context, *connect.Request[v1.ProxyListTrackerIssuesRequest]) (*connect.Response[v1.ProxyListTrackerIssuesResponse], error)
	// Per-repo proxies for web repo management. Route to the daemon named by
	// daemon_id and address the repo by repo_id. Reads/updates are secret-masked
	// (RepoSettings); writes carry tri-state SecretUpdate + expected_updated_at.
	ProxyGetRepo(context.Context, *connect.Request[v1.ProxyGetRepoRequest]) (*connect.Response[v1.ProxyGetRepoResponse], error)
	ProxyUpdateRepo(context.Context, *connect.Request[v1.ProxyUpdateRepoRequest]) (*connect.Response[v1.ProxyUpdateRepoResponse], error)
	ProxyRemoveRepo(context.Context, *connect.Request[v1.ProxyRemoveRepoRequest]) (*connect.Response[v1.ProxyRemoveRepoResponse], error)
	// Cron-job proxies for web cron-job management. ProxyListCronJobs aggregates
	// across all of the caller's live daemons; the mutating proxies route to the
	// daemon named by daemon_id and address the job by id.
	ProxyListCronJobs(context.Context, *connect.Request[v1.ProxyListCronJobsRequest]) (*connect.Response[v1.ProxyListCronJobsResponse], error)
	ProxyCreateCronJob(context.Context, *connect.Request[v1.ProxyCreateCronJobRequest]) (*connect.Response[v1.ProxyCreateCronJobResponse], error)
	ProxyUpdateCronJob(context.Context, *connect.Request[v1.ProxyUpdateCronJobRequest]) (*connect.Response[v1.ProxyUpdateCronJobResponse], error)
	ProxyDeleteCronJob(context.Context, *connect.Request[v1.ProxyDeleteCronJobRequest]) (*connect.Response[v1.ProxyDeleteCronJobResponse], error)
	ProxyRunCronJobNow(context.Context, *connect.Request[v1.ProxyRunCronJobNowRequest]) (*connect.Response[v1.ProxyRunCronJobNowResponse], error)
	// Daemon-scoped account-management proxies for the web Settings > Accounts
	// section. Unlike ProxyListAccounts (session-scoped, switch picker) these
	// route to the daemon named by daemon_id, since a Settings-level manager is
	// not session-scoped. Accounts stay metadata only on the wire — the add /
	// refresh requests carry an inbound-only credential blob (consumed straight
	// into the daemon keyring, never echoed back). Each proxy forwards 1:1 to the
	// existing daemon account.go handler via a reverse-stream OrchestratorCommand.
	ProxyManageListAccounts(context.Context, *connect.Request[v1.ProxyManageListAccountsRequest]) (*connect.Response[v1.ProxyManageListAccountsResponse], error)
	ProxyAddAccount(context.Context, *connect.Request[v1.ProxyAddAccountRequest]) (*connect.Response[v1.ProxyAddAccountResponse], error)
	ProxyRefreshAccount(context.Context, *connect.Request[v1.ProxyRefreshAccountRequest]) (*connect.Response[v1.ProxyRefreshAccountResponse], error)
	ProxyUpdateAccount(context.Context, *connect.Request[v1.ProxyUpdateAccountRequest]) (*connect.Response[v1.ProxyUpdateAccountResponse], error)
	ProxyRemoveAccount(context.Context, *connect.Request[v1.ProxyRemoveAccountRequest]) (*connect.Response[v1.ProxyRemoveAccountResponse], error)
	ProxyTestAccount(context.Context, *connect.Request[v1.ProxyTestAccountRequest]) (*connect.Response[v1.ProxyTestAccountResponse], error)
	// Read-tier MCP gateway parity (BOS-401). Session-scoped reads route to the
	// owning daemon via FindSessionDaemon; session-less reads aggregate across the
	// caller's Ready daemons via the shared resolver.
	// ProxyListChats reads a session's chats (routes by session_id).
	ProxyListChats(context.Context, *connect.Request[v1.ProxyListChatsRequest]) (*connect.Response[v1.ProxyListChatsResponse], error)
	// ProxyGetSessionStatuses fans out per session_id (FindSessionDaemon), skipping
	// unknown ids, and unions the returned SessionStatusEntry values.
	ProxyGetSessionStatuses(context.Context, *connect.Request[v1.ProxyGetSessionStatusesRequest]) (*connect.Response[v1.ProxyGetSessionStatusesResponse], error)
	// ProxyListCheckSnapshots reads a session's recent CI check snapshots (routes by session_id).
	ProxyListCheckSnapshots(context.Context, *connect.Request[v1.ProxyListCheckSnapshotsRequest]) (*connect.Response[v1.ProxyListCheckSnapshotsResponse], error)
	// ProxyListAgentsAggregated aggregates installed agents across the caller's
	// Ready daemons (session-less; distinct from the daemon-scoped ProxyListAgents).
	ProxyListAgentsAggregated(context.Context, *connect.Request[v1.ProxyListAgentsAggregatedRequest]) (*connect.Response[v1.ProxyListAgentsAggregatedResponse], error)
	// ProxyListPlugins aggregates configured plugins across the caller's Ready daemons.
	ProxyListPlugins(context.Context, *connect.Request[v1.ProxyListPluginsRequest]) (*connect.Response[v1.ProxyListPluginsResponse], error)
	// ProxyGetCronJob returns the first Ready daemon that owns the id (NotFound if none).
	ProxyGetCronJob(context.Context, *connect.Request[v1.ProxyGetCronJobRequest]) (*connect.Response[v1.ProxyGetCronJobResponse], error)
	// ProxyRepairDoctor merges repair-doctor reports across the caller's Ready daemons.
	ProxyRepairDoctor(context.Context, *connect.Request[v1.ProxyRepairDoctorRequest]) (*connect.Response[v1.ProxyRepairDoctorResponse], error)
	// Destructive-tier MCP gateway parity (BOS-404). Session-scoped destructive
	// ops route to the owning daemon via FindSessionDaemon (NotFound for a
	// missing/foreign session); empty_trash is daemon-wide and aggregates across
	// the caller's Ready daemons via the shared resolver.
	// ProxyCloseSession closes (abandons) a session, returning the updated Session.
	ProxyCloseSession(context.Context, *connect.Request[v1.ProxyCloseSessionRequest]) (*connect.Response[v1.ProxyCloseSessionResponse], error)
	// ProxyResurrectSession restores an archived session, returning the updated Session.
	ProxyResurrectSession(context.Context, *connect.Request[v1.ProxyResurrectSessionRequest]) (*connect.Response[v1.ProxyResurrectSessionResponse], error)
	// ProxyRemoveSession permanently removes a session and its worktree (Ok-only).
	ProxyRemoveSession(context.Context, *connect.Request[v1.ProxyRemoveSessionRequest]) (*connect.Response[v1.ProxyRemoveSessionResponse], error)
	// ProxyEmptyTrash permanently deletes archived sessions across the caller's
	// Ready daemons, summing each daemon's deleted_count.
	ProxyEmptyTrash(context.Context, *connect.Request[v1.ProxyEmptyTrashRequest]) (*connect.Response[v1.ProxyEmptyTrashResponse], error)
	// Mutating MCP gateway parity (BOS-402). Session-scoped mutations route to the
	// owning daemon via FindSessionDaemon; chat-scoped mutations via
	// FindDaemonForChat(agent_session_id). A foreign entity resolves to NotFound,
	// so no cross-user mutation can dispatch.
	// ProxyRetrySession retries a failed session (routes by session_id).
	ProxyRetrySession(context.Context, *connect.Request[v1.ProxyRetrySessionRequest]) (*connect.Response[v1.ProxyRetrySessionResponse], error)
	// ProxyUpdateSession updates a session's title/tracker (routes by session_id).
	ProxyUpdateSession(context.Context, *connect.Request[v1.ProxyUpdateSessionRequest]) (*connect.Response[v1.ProxyUpdateSessionResponse], error)
	// ProxyLinkSessionPR attaches an existing PR to a session (routes by session_id).
	ProxyLinkSessionPR(context.Context, *connect.Request[v1.ProxyLinkSessionPRRequest]) (*connect.Response[v1.ProxyLinkSessionPRResponse], error)
	// ProxyUpdateChatTitle renames a chat (routes by agent_session_id).
	ProxyUpdateChatTitle(context.Context, *connect.Request[v1.ProxyUpdateChatTitleRequest]) (*connect.Response[v1.ProxyUpdateChatTitleResponse], error)
	// ProxyReportChatStatus forwards chat status heartbeats. All reports must
	// resolve to the caller's own chats on a single daemon.
	ProxyReportChatStatus(context.Context, *connect.Request[v1.ProxyReportChatStatusRequest]) (*connect.Response[v1.ProxyReportChatStatusResponse], error)
	// GitHub-callback proxies for remote-CLI callback management (BOS-469). All
	// route to the owning daemon by target_chat_id via FindDaemonForChat, reusing
	// the caller's own auth — a foreign chat resolves to NotFound so no cross-user
	// registration can dispatch. Create/Delete require target_chat_id; List routes
	// by target_chat_id when set, else aggregates across the caller's Ready daemons.
	ProxyCreateGithubCallback(context.Context, *connect.Request[v1.ProxyCreateGithubCallbackRequest]) (*connect.Response[v1.ProxyCreateGithubCallbackResponse], error)
	ProxyListGithubCallbacks(context.Context, *connect.Request[v1.ProxyListGithubCallbacksRequest]) (*connect.Response[v1.ProxyListGithubCallbacksResponse], error)
	ProxyDeleteGithubCallback(context.Context, *connect.Request[v1.ProxyDeleteGithubCallbackRequest]) (*connect.Response[v1.ProxyDeleteGithubCallbackResponse], error)
	// Notes proxies for remote-CLI and hosted-gateway note management (BOS-552).
	// A note is repo-scoped, so all five route to the owning daemon by repo_id,
	// reusing the caller's own auth — a foreign repo resolves to NotFound so no
	// cross-user note access can dispatch. Create/Get/Update/Delete require
	// repo_id; List routes by repo_id when set, else aggregates across the
	// caller's Ready daemons.
	ProxyCreateNote(context.Context, *connect.Request[v1.ProxyCreateNoteRequest]) (*connect.Response[v1.ProxyCreateNoteResponse], error)
	ProxyGetNote(context.Context, *connect.Request[v1.ProxyGetNoteRequest]) (*connect.Response[v1.ProxyGetNoteResponse], error)
	ProxyListNotes(context.Context, *connect.Request[v1.ProxyListNotesRequest]) (*connect.Response[v1.ProxyListNotesResponse], error)
	ProxyUpdateNote(context.Context, *connect.Request[v1.ProxyUpdateNoteRequest]) (*connect.Response[v1.ProxyUpdateNoteResponse], error)
	ProxyDeleteNote(context.Context, *connect.Request[v1.ProxyDeleteNoteRequest]) (*connect.Response[v1.ProxyDeleteNoteResponse], error)
	// Streams the live chat list (and per-chat statuses) for a session through
	// the orchestrator. Bosso fans out the daemon's ChatDelta / ChatStatusDelta
	// events to subscribed web clients. Terminates with DaemonOffline if the
	// owning daemon disconnects.
	ProxyStreamChats(context.Context, *connect.Request[v1.ProxyStreamChatsRequest], *connect.ServerStream[v1.ProxyChatListEvent]) error
	// IssueAttachToken returns a short-lived JWT bound to (user, session,
	// chat, scope) that the browser uses to authenticate the /ws/attach
	// WebSocket handshake. TTL ~5 minutes.
	IssueAttachToken(context.Context, *connect.Request[v1.IssueAttachTokenRequest]) (*connect.Response[v1.IssueAttachTokenResponse], error)
	// TerminalStream is the bossd-initiated bidirectional channel that
	// carries terminal-attach traffic for the web /ws/attach feature.
	// Daemon opens lazily on the first attach and multiplexes attach_ids
	// inside it; isolated from the control-plane DaemonStream so keystroke
	// traffic never starves Stop/Pause/Transfer commands. Auth: per-daemon
	// X-Daemon-Token + WorkOS JWT, same as DaemonStream.
	//
	// Stream-type orientation matches DaemonStream: bossd is the gRPC
	// client, so the request stream carries daemon→bosso messages
	// (TerminalServerMessage) and the response stream carries bosso→daemon
	// messages (TerminalClientMessage). The "Client"/"Server" prefix refers
	// to the web feature's bosso-server / browser-client perspective, not
	// the gRPC roles. See docs/plans/2026-04-26-web-tmux-attach.md.
	TerminalStream(context.Context, *connect.BidiStream[v1.TerminalServerMessage, v1.TerminalClientMessage]) error
	// Webhook configuration management
	CreateWebhookConfig(context.Context, *connect.Request[v1.CreateWebhookConfigRequest]) (*connect.Response[v1.CreateWebhookConfigResponse], error)
	ListWebhookConfigs(context.Context, *connect.Request[v1.ListWebhookConfigsRequest]) (*connect.Response[v1.ListWebhookConfigsResponse], error)
	DeleteWebhookConfig(context.Context, *connect.Request[v1.DeleteWebhookConfigRequest]) (*connect.Response[v1.DeleteWebhookConfigResponse], error)
	// GitHub App repository registration. User-authenticated.
	GetGitHubAppInstallURL(context.Context, *connect.Request[v1.GetGitHubAppInstallURLRequest]) (*connect.Response[v1.GetGitHubAppInstallURLResponse], error)
	CompleteGitHubAppSetup(context.Context, *connect.Request[v1.CompleteGitHubAppSetupRequest]) (*connect.Response[v1.CompleteGitHubAppSetupResponse], error)
	ListGitHubAppRepos(context.Context, *connect.Request[v1.ListGitHubAppReposRequest]) (*connect.Response[v1.ListGitHubAppReposResponse], error)
	DisconnectGitHubAppRepo(context.Context, *connect.Request[v1.DisconnectGitHubAppRepoRequest]) (*connect.Response[v1.DisconnectGitHubAppRepoResponse], error)
	// Cloud billing and access. User-authenticated.
	GetCloudAccessStatus(context.Context, *connect.Request[v1.GetCloudAccessStatusRequest]) (*connect.Response[v1.GetCloudAccessStatusResponse], error)
	CreateCheckoutSession(context.Context, *connect.Request[v1.CreateCheckoutSessionRequest]) (*connect.Response[v1.CreateCheckoutSessionResponse], error)
	CreateBillingPortalSession(context.Context, *connect.Request[v1.CreateBillingPortalSessionRequest]) (*connect.Response[v1.CreateBillingPortalSessionResponse], error)
	RefreshCloudEntitlements(context.Context, *connect.Request[v1.RefreshCloudEntitlementsRequest]) (*connect.Response[v1.RefreshCloudEntitlementsResponse], error)
	// Bug reporting (ctrl+g in TUI; ctrl+b is a deprecated alias). Unauthenticated; optionally
	// resolves the caller's identity when a bearer token is present.
	ReportBug(context.Context, *connect.Request[v1.ReportBugRequest]) (*connect.Response[v1.ReportBugResponse], error)
}

